export const promiseCache=new Map;export const responseCache=new Map;export function getCache(cacheKey){const buildCache=(cacheKey,cache)=>({clear:()=>cache.delete(cacheKey),get:()=>cache.get(cacheKey),set:data=>cache.set(cacheKey,data)}),promise=buildCache(cacheKey,promiseCache),response=buildCache(cacheKey,responseCache);return{clear:()=>{promise.clear(),response.clear()},promise:promise,response:response}}export async function withCache(fn,{cacheKey:cacheKey,cacheTime:cacheTime=Number.POSITIVE_INFINITY}){const cache=getCache(cacheKey),response=cache.response.get();if(response&&cacheTime>0){if((new Date).getTime()-response.created.getTime()<cacheTime)return response.data}let promise=cache.promise.get();promise||(promise=fn(),cache.promise.set(promise));try{const data=await promise;return cache.response.set({created:new Date,data:data}),data}finally{cache.promise.clear()}}