import{getEnsAddressQueryOptions}from"@wagmi/core/query";import{useQuery}from"../utils/query.js";import{useChainId}from"./useChainId.js";import{useConfig}from"./useConfig.js";export function useEnsAddress(parameters={}){const{name:name,query:query={}}=parameters,config=useConfig(parameters),chainId=useChainId({config:config}),options=getEnsAddressQueryOptions(config,{...parameters,chainId:parameters.chainId??chainId}),enabled=Boolean(name&&(query.enabled??!0));return useQuery({...query,...options,enabled:enabled})}