import{getTransactionCount as viem_getTransactionCount}from"viem/actions";import{getAction}from"../utils/getAction.js";export async function getTransactionCount(config,parameters){const{address:address,blockNumber:blockNumber,blockTag:blockTag,chainId:chainId}=parameters,client=config.getClient({chainId:chainId});return getAction(client,viem_getTransactionCount,"getTransactionCount")(blockNumber?{address:address,blockNumber:blockNumber}:{address:address,blockTag:blockTag})}