import{readContractQueryOptions,structuralSharing}from"@wagmi/core/query";import{useQuery}from"../utils/query.js";import{useChainId}from"./useChainId.js";import{useConfig}from"./useConfig.js";export function useReadContract(parameters={}){const{abi:abi,address:address,functionName:functionName,query:query={}}=parameters,code=parameters.code,config=useConfig(parameters),chainId=useChainId({config:config}),options=readContractQueryOptions(config,{...parameters,chainId:parameters.chainId??chainId}),enabled=Boolean((address||code)&&abi&&functionName&&(query.enabled??!0));return useQuery({...query,...options,enabled:enabled,structuralSharing:query.structuralSharing??structuralSharing})}