import{Easing}from"react-native-reanimated";export const getKeyboardAnimationConfigs=(easing,duration)=>{switch(easing){case"easeIn":return{easing:Easing.in(Easing.ease),duration:duration};case"easeOut":return{easing:Easing.out(Easing.ease),duration:duration};case"easeInEaseOut":return{easing:Easing.inOut(Easing.ease),duration:duration};case"linear":return{easing:Easing.linear,duration:duration};case"keyboard":return{damping:500,stiffness:1e3,mass:3,overshootClamping:!0,restDisplacementThreshold:10,restSpeedThreshold:10}}};