import{hydrate as domLegacyHydrate,render as domLegacyRender}from"react-dom";import{createRoot as domCreateRoot,hydrateRoot as domHydrateRoot}from"react-dom/client";import unmountComponentAtNode from"../unmountComponentAtNode";import{createSheet}from"../StyleSheet/dom";export function hydrate(element,root){return createSheet(root),domHydrateRoot(root,element)}export function render(element,root){createSheet(root);var reactRoot=domCreateRoot(root);return reactRoot.render(element),reactRoot}export function hydrateLegacy(element,root,callback){return createSheet(root),domLegacyHydrate(element,root,callback),{unmount:function(){return unmountComponentAtNode(root)}}}export default function renderLegacy(element,root,callback){return createSheet(root),domLegacyRender(element,root,callback),{unmount:function(){return unmountComponentAtNode(root)}}}