import{multicall as viem_multicall}from"viem/actions";import{getAction}from"../utils/getAction.js";export async function multicall(config,parameters){const{allowFailure:allowFailure=!0,chainId:chainId,contracts:contracts,...rest}=parameters,client=config.getClient({chainId:chainId});return getAction(client,viem_multicall,"multicall")({allowFailure:allowFailure,contracts:contracts,...rest})}