import{ChainDisconnectedError,ProviderDisconnectedError,createTransport,hexToNumber,withRetry,withTimeout}from"viem";export function unstable_connector(connector,config={}){const{type:type}=connector,{key:key="connector",name:name="Connector",retryDelay:retryDelay}=config;return parameters=>{const{chain:chain,connectors:connectors}=parameters,retryCount=config.retryCount??parameters.retryCount;return createTransport({key:key,name:name,request:async({method:method,params:params})=>{const connector=connectors?.getState().find((c=>c.type===type));if(!connector)throw new ProviderDisconnectedError(new Error(`Could not find connector of type "${type}" in \`connectors\` passed to \`createConfig\`.`));const provider=await connector.getProvider({chainId:chain?.id});if(!provider)throw new ProviderDisconnectedError(new Error("Provider is disconnected."));const chainId=hexToNumber(await withRetry((()=>withTimeout((()=>provider.request({method:"eth_chainId"})),{timeout:100}))));if(chain&&chainId!==chain.id)throw new ChainDisconnectedError(new Error(`The current chain of the connector (id: ${chainId}) does not match the target chain for the request (id: ${chain.id} – ${chain.name}).`));const body={method:method,params:params};return provider.request(body)},retryCount:retryCount,retryDelay:retryDelay,type:"connector"})}}